// Prepara los dos mensajes del vale: uno para el cliente y otro para la tienda.
// Los importes son los que devuelve la API: aqui no se recalcula nada.
// La API da las fechas como AAAA-MM-DD; en los mensajes van como dia/mes/año.
const fechaES = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2].slice(0, 2) + '/' + t[1] + '/' + t[0] : String(f ?? '');
};
const entrada = $input.first().json ?? {};
const datos = entrada.datos ?? entrada;
const apartado = datos.apartado ?? entrada.apartado ?? {};
const vale = datos.vale ?? entrada.vale ?? {};

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const producto = [apartado.producto, apartado.talla].filter(Boolean).join(' · ');
const cliente = apartado.cliente ?? '';
// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const emailCliente = String(apartado.email ?? '').trim();

const cuerpoCliente = [
  'Hola ' + cliente + ',',
  '',
  'Tu apartado de ' + producto + ' ha llegado a su fecha limite (' + fechaES(apartado.fecha_limite) + ') y se ha cerrado.',
  '',
  'Lo que habias abonado se convierte en un vale de compra:',
  '',
  'Codigo del vale: ' + (vale.codigo ?? ''),
  'Importe del vale: ' + euros(vale.importe),
  '',
  'Puedes pasar por la tienda a cambiarlo por tus zapatos. El vale no se devuelve en efectivo.',
  '',
  'Un saludo,',
  'Zapateria Paso Firme',
].join('\n');

const cuerpoTienda = [
  'Se ha vencido un apartado y vuelve a la venta:',
  '',
  'Apartado #' + (apartado.id ?? ''),
  'Cliente: ' + cliente,
  'Producto: ' + producto,
  'Abonado: ' + euros(vale.importe),
  'Vale: ' + (vale.codigo ?? ''),
  '',
  'Este par vuelve a estar en la tienda para venderlo.',
].join('\n');

return [
  {
    json: {
      canal: 'email',
      email: emailCliente,
      asunto: 'Tu vale de compra · Paso Firme',
      cuerpo: cuerpoCliente,
    },
  },
  {
    json: {
      canal: 'email',
      email: emailTienda,
      asunto: 'Apartado vencido #' + (apartado.id ?? '') + ' · vuelve a la venta',
      cuerpo: cuerpoTienda,
    },
  },
];
